export function encode(input) {
  if (typeof input !== 'string') throw new TypeError('encode expects a string');
  let out = '';
  let run = 0;
  for (let i = 0; i < input.length; i += 1) {
    run += 1;
    if (input[i + 1] !== input[i]) {
      out = `${out}${run}x${input[i]}`;
      run = 0;
    }
  }
  return out;
}

export function decode(input) {
  if (typeof input !== 'string') throw new TypeError('decode expects a string');
  let out = '';
  let i = 0;
  while (i < input.length) {
    let count = '';
    while (i < input.length && input[i] >= '0' && input[i] <= '9') {
      count = count + input[i];
      i += 1;
    }
    if (count === '') throw new SyntaxError('missing count');
    if (count.length > 1 && count[0] === '0') throw new SyntaxError('leading zero');
    if (Number(count) === 0) throw new SyntaxError('zero count');
    if (input[i] !== 'x') throw new SyntaxError('missing x');
    i += 1;
    if (i >= input.length) throw new SyntaxError('missing character');
    out = out + input[i].repeat(Number(count));
    i += 1;
  }
  return out;
}
